    def furthestBuilding(self, H: List[int], B: int, L: int) -> int:
        heap = []
        for i in range(len(H) - 1):
            diff = H[i+1] - H[i]
            if diff > 0:
                if L > 0:
                    heappush(heap, diff)
                    L -= 1
                elif heap and diff > heap[0]:
                    heappush(heap, diff)
                    B -= heappop(heap)
                else: B -= diff
                if B < 0: return i
        return len(H) - 1

class Solution:
    def stoneGameVI(self, A, B):
        G  = [a+b for a,b in zip(A,B)]
        G.sort()
        L  = len(A)
        d  = -sum(B) + sum( G[i] for i in range(L-1,-1,-2) )
        return 1 if d>0 else ( -1 if d<0 else 0 )

